std::FILE* fp = std::fopen("/dev/urandom", "rb");
if (fp == nullptr)
    throw std::runtime_error(
        "random_seed_from_os: cannot open /dev/urandom (no OS entropy available)");
const std::size_t rd = std::fread(buf.data(), 1, nbytes, fp);
std::fclose(fp);
if (rd != nbytes)
    throw std::runtime_error(
        "random_seed_from_os: short read from /dev/urandom");

